import json
h,w=17,30
g=[[0]*w for _ in range(h)]
mask={(0,c) for c in range(5)} | {(1,2),(2,1),(2,2),(2,3)} | {(3,c) for c in range(5)} | {(4,2)}
# Demo rule: vertically align the repeated same-shaped colored objects to the topmost object's row.
# In this test the topmost object's bbox begins at row 2. Preserve each object's color and x position.
for color,left in [(3,2),(1,9),(4,14),(8,21)]:
    for dr,dc in mask:
        g[2+dr][left+dc]=color
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

